using ImageMagick;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Xml.Linq;
namespace Tangerine;

public static class AuditSuite
{
    public static async Task<bool> Run(App app, string directory, bool documentsOnly = false)
    {
        Directory.CreateDirectory(directory);
        var reports = new List<object>(); var output = Path.Combine(directory, "outputs"); var input = Path.Combine(directory, "inputs"); Directory.CreateDirectory(input); Directory.CreateDirectory(output);
        var engine = new Engine(new AppSettings { OutputDirectory = output, EngineDirectory = Environment.GetEnvironmentVariable("TANGERINE_ENGINE_DIR") ?? app.Settings.EngineDirectory });
        int failed = 0;
        async Task Test(string name, Func<Task> action) { var clock = Stopwatch.StartNew(); try { await action(); reports.Add(new { name, passed = true, ms = clock.ElapsedMilliseconds }); } catch (Exception ex) { failed++; reports.Add(new { name, passed = false, error = ex.ToString(), ms = clock.ElapsedMilliseconds }); } File.WriteAllText(Path.Combine(directory, "audit-results.json"), JsonSerializer.Serialize(reports, new JsonSerializerOptions { WriteIndented = true })); }
        void Check(bool ok, string message) { if (!ok) throw new InvalidDataException(message); }
        async Task Throws(Func<Task> action) { try { await action(); } catch (ArgumentException) { return; } catch (InvalidOperationException) { return; } catch (IOException) { return; } catch (InvalidDataException) { return; } throw new Exception("Invalid operation was reported as successful."); }
        Task<List<string>> Convert(string file, string format) => engine.Run(new[] { file }, new(format, format, "Convert to " + format), WheelMode.Convert, new(), CancellationToken.None);
        Task<List<string>> Tool(string[] files, string id, OperationOptions? options = null, CancellationToken ct = default) => engine.Run(files, new(id, id, id), WheelMode.Tools, options ?? new(), ct);
        async Task<JsonDocument> Probe(string file) => JsonDocument.Parse(await Engine.Process(engine.FindTool("ffprobe")!, new[] { "-v", "error", "-show_format", "-show_streams", "-of", "json", file }, CancellationToken.None));
        async Task<double> Duration(string file) { using var p = await Probe(file); return double.Parse(p.RootElement.GetProperty("format").GetProperty("duration").GetString()!, CultureInfo.InvariantCulture); }
        async Task<float[]> Samples(string file) { var raw = Path.Combine(input, Guid.NewGuid() + ".f32"); await Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-i", file, "-vn", "-ac", "1", "-ar", "8000", "-f", "f32le", raw }, CancellationToken.None); var bytes = File.ReadAllBytes(raw); File.Delete(raw); var values = new float[bytes.Length / 4]; Buffer.BlockCopy(bytes, 0, values, 0, bytes.Length); return values; }
        double Rms(float[] samples, int start, int count) => Math.Sqrt(samples.Skip(start).Take(count).Select(x => (double)x * x).Average());
        double Power(float[] samples, int start, int count, double frequency) { double real = 0, imaginary = 0; for (int i = 0; i < count; i++) { double angle = 2 * Math.PI * frequency * i / 8000; real += samples[start + i] * Math.Cos(angle); imaginary += samples[start + i] * Math.Sin(angle); } return real * real + imaginary * imaginary; }

        var png = Path.Combine(input, "colour source.png"); using (var im = new MagickImage("gradient:#FF7700-#1122EE", 160, 120)) im.Write(png);
        var original = SHA256.HashData(File.ReadAllBytes(png));
        if (!documentsOnly)
        {
            var imageSources = new List<string> { png };
            foreach (var ext in new[] { "jpg", "webp", "heic", "avif", "tiff", "bmp" }) await Test("Prepare image input " + ext, async () => imageSources.Add((await Convert(png, ext))[0]));
            var svg = Path.Combine(input, "vector.svg"); File.WriteAllText(svg, "<svg xmlns='http://www.w3.org/2000/svg' width='160' height='120'><rect width='160' height='120' fill='#ff7700'/></svg>"); imageSources.Add(svg);
            foreach (var source in imageSources) foreach (var target in Catalog.Conversions(source).Select(x => x.Id).ToArray()) await Test($"Image pair {Catalog.Extension(source)} → {target}", async () => { var result = (await Convert(source, target))[0]; if (target == "pdf") { using var doc = PdfSharp.Pdf.IO.PdfReader.Open(result, PdfSharp.Pdf.IO.PdfDocumentOpenMode.Import); Check(doc.PageCount == 1, "Missing page"); } else { using var im = new MagickImage(result); Check(im.Width == 160 && im.Height == 120, "Image dimensions changed"); } });
            foreach (var alias in new[] { "jpeg", "tif", "heif" }) await Test("Image alias " + alias, async () => { var source = imageSources.First(x => Catalog.Extension(x) == (alias == "jpeg" ? "jpg" : alias == "tif" ? "tiff" : "heic")); var file = Path.Combine(input, "alias." + alias); File.Copy(source, file); using var im = new MagickImage((await Convert(file, "png"))[0]); Check(im.Width == 160, "Alias not decoded"); });
            await Test("All batch PDF images become pages", async () => { var p = (await Tool(new[] { png, imageSources[1], svg }, "createpdf"))[0]; using var doc = PdfSharp.Pdf.IO.PdfReader.Open(p, PdfSharp.Pdf.IO.PdfDocumentOpenMode.Import); Check(doc.PageCount == 3, "Batch lost pages"); });
            await Test("Invalid crop rolls back output", async () => await Throws(async () => { await Tool(new[] { png }, "crop", new() { X = 150, Y = 0, Width = 30, Height = 20 }); }));
            await Test("NaN and infinity options are rejected", async () => await Throws(async () => { await Tool(new[] { png }, "edit", new() { Brightness = double.NaN }); }));
            await Test("Background preserves transparent input pixels", async () => { var p = Path.Combine(input, "transparent.png"); using (var im = new MagickImage(MagickColors.Transparent, 30, 30)) im.Write(p); var framed = (await Tool(new[] { p }, "background", new() { Padding = 10, Radius = 4, Color = "#FF5900" }))[0]; using var result = new MagickImage(framed); using var pixels = result.GetPixels(); var pixel = pixels.GetPixel(25, 25).ToColor()!; Check(pixel.R > 100 && pixel.G < 230, "Transparent center turned into a dark/opaque block"); });
            await Test("Multi-page TIFF → PDF retains every page", async () => { var tiff = Path.Combine(input, "multipage.tiff"); using (var collection = new MagickImageCollection()) { collection.Add(new MagickImage(MagickColors.Red, 20, 30)); collection.Add(new MagickImage(MagickColors.Blue, 20, 30)); collection.Write(tiff); } var result = (await Convert(tiff, "pdf"))[0]; using var doc = PdfSharp.Pdf.IO.PdfReader.Open(result, PdfSharp.Pdf.IO.PdfDocumentOpenMode.Import); Check(doc.PageCount == 2, "Multi-page source was silently truncated"); });

            var audio = Path.Combine(input, "tone.wav"); var video = Path.Combine(input, "clip.mp4"); var silent = Path.Combine(input, "silent.mp4");
            await Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-f", "lavfi", "-i", "sine=frequency=440:duration=2", "-af", "volume=0.1", audio }, CancellationToken.None);
            await Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-f", "lavfi", "-i", "testsrc=size=160x120:rate=20:duration=2", "-i", audio, "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", video }, CancellationToken.None);
            await Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-i", video, "-an", "-c:v", "copy", silent }, CancellationToken.None);
            var audioSources = new List<string> { audio }; foreach (var ext in new[] { "mp3", "m4a", "flac", "ogg", "opus", "aiff", "wma" }) await Test("Prepare audio input " + ext, async () => audioSources.Add((await Convert(audio, ext))[0]));
            foreach (var source in audioSources) foreach (var target in Catalog.Conversions(source).Select(x => x.Id).ToArray()) await Test($"Audio pair {Catalog.Extension(source)} → {target}", async () => { var result = (await Convert(source, target))[0]; using var probe = await Probe(result); Check(probe.RootElement.GetProperty("streams").EnumerateArray().Any(x => x.GetProperty("codec_type").GetString() == "audio"), "No audio stream"); var duration = await Duration(result); Check(duration > 1.7 && duration < 2.5, "Audio duration changed unexpectedly"); });
            var videos = new List<string> { video }; foreach (var ext in new[] { "mov", "mkv", "webm", "avi", "wmv", "gif" }) await Test("Prepare video input " + ext, async () => videos.Add((await Convert(video, ext))[0]));
            foreach (var source in videos) foreach (var target in Catalog.Conversions(source).Select(x => x.Id).ToArray()) await Test($"Video pair {Catalog.Extension(source)} → {target}", async () => { var result = (await Convert(source, target))[0]; using var probe = await Probe(result); Check(probe.RootElement.GetProperty("streams").EnumerateArray().Any(x => x.GetProperty("codec_type").GetString() == (target == "mp3" ? "audio" : "video")), "Missing expected media stream"); Check(await Duration(result) > 1.5, "Video is empty or truncated"); });
            await Test("Mute removes audio while preserving video", async () => { var p = (await Tool(new[] { video }, "mute"))[0]; using var probe = await Probe(p); Check(!probe.RootElement.GetProperty("streams").EnumerateArray().Any(x => x.GetProperty("codec_type").GetString() == "audio"), "Muted clip still has audio"); Check(Math.Abs(await Duration(p) - 2) < .2, "Muted clip length changed"); });
            await Test("Trim yields requested duration", async () => { var p = (await Tool(new[] { video }, "trim", new() { Start = .5, Duration = .75 }))[0]; Check(Math.Abs(await Duration(p) - .75) < .18, "Trim duration incorrect"); });
            await Test("Trim outside file is rejected", async () => await Throws(async () => { await Tool(new[] { video }, "trim", new() { Start = 99, Duration = 1 }); }));
            await Test("Odd-pixel video crop has exact bounds", async () => { var p = (await Tool(new[] { video }, "crop", new() { X = 3, Y = 3, Width = 99, Height = 77 }))[0]; using var probe = await Probe(p); var stream = probe.RootElement.GetProperty("streams").EnumerateArray().First(x => x.GetProperty("codec_type").GetString() == "video"); Check(stream.GetProperty("width").GetInt32() == 99 && stream.GetProperty("height").GetInt32() == 77, "Crop dimensions were rounded silently"); });
            await Test("Video redaction outside image is rejected", async () => await Throws(async () => { await Tool(new[] { video }, "redact", new() { X = 900, Y = 0, Width = 40, Height = 40 }); }));
            await Test("Silent video speed changes duration", async () => { var p = (await Tool(new[] { silent }, "speed", new() { Speed = 2 }))[0]; Check(Math.Abs(await Duration(p) - 1) < .25, "Silent speed change failed"); });
            await Test("Slow video speed changes duration", async () => { var p = (await Tool(new[] { video }, "speed", new() { Speed = .5 }))[0]; Check(Math.Abs(await Duration(p) - 4) < .3, "Slow playback duration incorrect"); });
            await Test("Join mixed silent and audio clips", async () => { var p = (await Tool(new[] { silent, video }, "join"))[0]; Check(Math.Abs(await Duration(p) - 4) < .4, "Joined duration incorrect"); });
            await Test("Normalize measurably increases quiet audio", async () => { var p = (await Tool(new[] { audio }, "normalize"))[0]; var before = await Samples(audio); var after = await Samples(p); Check(Rms(after, 1000, 8000) > Rms(before, 1000, 8000) * 3, "Normalization had no effect"); });
            await Test("Bleep replaces selected interval and leaves the rest", async () => { var p = (await Tool(new[] { audio }, "bleep", new() { Start = .5, Duration = .5 }))[0]; var before = await Samples(audio); var after = await Samples(p); Check(Power(after, 4500, 2000, 1000) > Power(after, 4500, 2000, 440) * 20, "1000 Hz bleep did not replace the original tone"); Check(Math.Abs(Rms(after, 9500, 2500) - Rms(before, 9500, 2500)) < .005, "Unselected audio changed"); });
            await Test("Stereo conversion has two channels", async () => { var p = (await Tool(new[] { audio }, "channels", new() { Channels = 2 }))[0]; using var probe = await Probe(p); Check(probe.RootElement.GetProperty("streams")[0].GetProperty("channels").GetInt32() == 2, "Stereo channel count incorrect"); });
            await Test("Running process cancellation terminates FFmpeg", async () => { using var cts = new CancellationTokenSource(); var p = Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-re", "-f", "lavfi", "-i", "sine=frequency=440", "-f", "null", "-" }, cts.Token); await Task.Delay(400); cts.Cancel(); try { await p; throw new Exception("Process was not cancelled"); } catch (OperationCanceledException) { } });

            await Test("Subtitle numeric dialogue is preserved", () => { var text = Engine.Subtitles("1\n00:00:01,000 --> 00:00:02,000\n12345\n", "txt"); Check(text.Contains("12345"), "Numeric dialogue was deleted"); return Task.CompletedTask; });
            await Test("VTT notes and styles are excluded from plain text", () => { var text = Engine.Subtitles("WEBVTT\n\nNOTE secret note\nnot dialogue\n\n00:01.000 --> 00:02.000\nHello &amp; goodbye\n", "txt"); Check(!text.Contains("secret") && !text.Contains("WEBVTT") && text.Contains("Hello & goodbye"), "VTT metadata leaked into dialogue"); return Task.CompletedTask; });
            await Test("Plain GZIP extraction", async () => { var gz = Path.Combine(input, "payload.txt.gz"); using (var file = File.Create(gz)) using (var gzip = new GZipStream(file, CompressionMode.Compress)) gzip.Write(Encoding.UTF8.GetBytes("gzip payload")); var dir = (await Tool(new[] { gz }, "extract"))[0]; Check(File.ReadAllText(Path.Combine(dir, "payload.txt")) == "gzip payload", "Single-file GZIP did not extract"); });
            var rar = Environment.GetEnvironmentVariable("TANGERINE_RAR_FIXTURE"); if (!string.IsNullOrEmpty(rar)) await Test("RAR extraction and conversion to ZIP", async () => { var dir = (await Tool(new[] { rar }, "extract"))[0]; var files = Directory.GetFiles(dir, "*", SearchOption.AllDirectories); Check(files.Length > 0, "RAR extraction empty"); var zip = (await Convert(rar, "zip"))[0]; using var archive = ZipFile.OpenRead(zip); Check(archive.Entries.Count(x => !x.FullName.EndsWith('/')) == files.Length, "RAR conversion lost files"); });
            await Test("Malicious ZIP path rejected with no leaked output", async () => { var zip = Path.Combine(input, "traversal.zip"); using (var archive = ZipFile.Open(zip, ZipArchiveMode.Create)) { using var writer = new StreamWriter(archive.CreateEntry("../escaped.txt").Open()); writer.Write("escape"); } await Throws(async () => { await Tool(new[] { zip }, "extract"); }); Check(!Directory.GetFiles(directory, "escaped.txt", SearchOption.AllDirectories).Any(), "Zip escaped staging"); });

        }
        var text = Path.Combine(input, "document.txt"); File.WriteAllText(text, "Tangerine audit\nHello Unicode café नमस्ते\n12345\n");
        var markdown = Path.Combine(input, "document.md"); File.WriteAllText(markdown, "# Tangerine audit\n\nHello Unicode café नमस्ते\n");
        var html = Path.Combine(input, "rich.html"); File.WriteAllText(html, "<html><head><meta charset='utf-8'></head><body><h1>Tangerine audit</h1><p>Hello Unicode café नमस्ते</p><img src='colour source.png' width='160' height='120'></body></html>");
        var docs = new List<string> { text, markdown, html }; await Test("Prepare DOCX with linked image", async () => docs.Add((await Convert(html, "docx"))[0])); await Test("Prepare EPUB", async () => docs.Add((await Convert(text, "epub"))[0]));
        foreach (var source in docs.ToArray()) foreach (var target in Catalog.Conversions(source).Select(x => x.Id).ToArray()) await Test($"Document pair {Catalog.Extension(source)} → {target}", async () => { var result = (await Convert(source, target))[0]; if (target is "png" or "jpg") { Check(Directory.GetFiles(result).Length > 0, "No rendered pages"); } else if (target == "pdf") { using var pdf = UglyToad.PdfPig.PdfDocument.Open(result); Check(pdf.GetPages().Any(p => p.Text.Contains("Tangerine audit")), "Document text was lost"); } else if (target == "docx") { using var zip = ZipFile.OpenRead(result); Check(zip.GetEntry("word/document.xml") != null, "Invalid DOCX"); } else if (target == "epub") { using var zip = ZipFile.OpenRead(result); Check(zip.GetEntry("mimetype") != null, "Invalid EPUB"); } else Check(File.ReadAllText(result).Contains("Tangerine"), "Document output lost content"); });
        await Test("HTML → DOCX embeds its relative image", () => { using var zip = ZipFile.OpenRead(docs.First(x => Catalog.Extension(x) == "docx")); Check(zip.Entries.Any(x => x.FullName.StartsWith("word/media/")), "Relative image missing from DOCX"); return Task.CompletedTask; });
        await Test("DOCX → HTML is self-contained after staging cleanup", async () => { var file = (await Convert(docs.First(x => Catalog.Extension(x) == "docx"), "html"))[0]; var content = File.ReadAllText(file); Check(content.Contains("data:image/"), "HTML image resources were not embedded"); });
        await Test("Source image hash unchanged after all operations", () => { Check(original.SequenceEqual(SHA256.HashData(File.ReadAllBytes(png))), "Source was modified"); return Task.CompletedTask; });
        await Test("No staging directories remain", () => { Check(!Directory.GetDirectories(output, ".tangerine-*").Any(), "Staging directory leaked"); return Task.CompletedTask; });
        File.WriteAllText(Path.Combine(directory, "complete.json"), JsonSerializer.Serialize(new { checks = reports.Count, failed, passed = reports.Count - failed })); return failed == 0;
    }
}
